use crate::ciphers::jenkins::cipher::jenkins_digest;
use crate::ciphers::jenkins::keys::jenkins_default_key;
use crate::core::sample::sample_bytes;
use crate::core::timer::Stopwatch;

/// Time one digest pass over `input_len` generated bytes.
pub fn jenkins_measure(input_len: usize) -> u128 {
    let data = sample_bytes(input_len);
    let seed = jenkins_default_key();
    let watch = Stopwatch::start();
    let out = jenkins_digest(&data, seed);
    std::hint::black_box(out);
    watch.elapsed_ns()
}
